export function ic(p){return '<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+p+'</svg>';}
export function icf(p){return '<svg class="ico" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">'+p+'</svg>';}

