function figureList(cat){return FIGURES[cat]||[];}
function figName(cat,v){const f=figureList(cat).find(x=>x.id===v);return f?(lang==='en'?f.en:f.de):v;}
function figuresOf(a){return (a&&a.figures)?a.figures:[];}

